using System;

class Player
{
    static void Main()
    {
        string[] head = Console.ReadLine().Split(' ');
        int w = int.Parse(head[0]);
        int h = int.Parse(head[1]);
        int n = int.Parse(head[2]);
        int c = int.Parse(head[3]);

        char[][] board = new char[h][];
        for (int i = 0; i < h; i++) board[i] = Console.ReadLine().ToCharArray();

        for (int b = 0; b < n; b++)
        {
            int col = c;
            for (int row = 0; row < h; row++)
            {
                char peg = board[row][col];
                if (peg == '.') continue;
                board[row][col] = peg == '<' ? '>' : '<';
                col += peg == '<' ? -1 : 1;
            }
            Console.WriteLine(col);
        }
    }
}
